// 本期新增城市未出现在旧映射中，补充其省级归属，再同步省级汇总。
const newCityProvinces = { 定西: '甘肃', 武威: '甘肃', 张掖: '甘肃', 临夏: '甘肃', 吴忠: '宁夏', 固原: '宁夏', 七台河: '黑龙江', 山南: '西藏', 昌都: '西藏' };
const geoCountFields = ['newUsers', 'pageExposure', 'totalClicks', 'bannerClicks', 'algorithmExposure', 'algorithmClicks', 'configuredClicks', 'adClicks'];
function completeCurrentCityProvinces(data) {
  const unknown = data.provinces.find(row => row.province === '未知');
  data.cities.forEach(city => {
    const province = city.province === '未知' && newCityProvinces[city.city];
    if (!province) return;
    const target = data.provinces.find(row => row.province === province);
    geoCountFields.forEach(field => { target[field] += city[field]; unknown[field] -= city[field]; });
    city.province = province;
    city.mapping = '城市回填';
    data.meta.unmappedNewUsers -= city.newUsers;
  });
}
completeCurrentCityProvinces(LATEST_LOCAL_PACKAGE_GEO_DATA);
